#!/bin/sh
# CVE-2026-94285: byteM_parse_codeset must not read a multi-byte character's
# trailing bytes past the end of the input.
name=lcgen-byte-codeset tree=$1 work=$2 dir=$3
source_file=modules/lc/gen/lcGenConv.c
start='static CodeSet\nbyteM_parse_codeset('
end='\n}\n'
# XlibConf.h is generated by configure, which runs later; Debian builds with
# threads, and the control uses no Display fields.
mkdir -p "$work/inc/X11"
printf "#define XTHREADS 1\n#define XUSE_MTSAFE_API 1\n" > "$work/inc/X11/XlibConf.h"
includes="-I$work/inc -I$tree/include -I$tree/include/X11 -I$tree/src -I$tree/src/xlibi18n"
baseline_error='AddressSanitizer: heap-buffer-overflow\|insufficient space for an object'
. "$(dirname "$0")/../../../control-run.sh"
